<script>
	import { twMerge } from 'tailwind-merge';

	/**
	 * @typedef {Object} Props
	 * @property {boolean} [invert]
	 * @property {'xs' | 'sm' | 'md' | 'full'} [size]
	 */

	/** @type {Props} */
	let {
		invert = false,
		stickers = false,
		size = 'full',
		class: className,
		...restProps
	} = $props();
	const fill = invert ? 'white' : 'black';

	const sizeClasses = {
		xs: 'w-20 h-auto',
		sm: 'w-28 h-auto',
		md: 'w-48 h-auto',
		full: 'w-full h-auto'
	};

	const baseClass = $derived(sizeClasses[size] || sizeClasses.full);
	const mergedClass = $derived(twMerge(baseClass, className));
</script>

